static const unsigned char tx_mod[8][4] = {   /* bit k set: operator k+1 feeds this operator */
    { 2, 4, 8, 0 }, { 2, 12, 0, 0 }, { 6, 0, 8, 0 }, { 2, 4, 0, 0 },
    { 2, 0, 8, 0 }, { 8, 8, 8, 0 }, { 0, 0, 8, 0 }, { 0, 0, 0, 0 } };
static const unsigned char tx_car[8] = { 1, 1, 1, 9, 5, 7, 7, 15 };   /* bit k set: operator k+1 is a carrier */

static inline float tx_wave(int w, float ph)
{
    float s = sinf(6.2831853f * ph);
    switch (w) {
    case 0: return s;
    case 1: return s > 0.0f ? s : 0.0f;                                      /* half sine */
    case 2: return fabsf(s);                                                 /* full rectified */
    case 3: return fmodf(ph, 0.5f) < 0.25f ? fabsf(s) : 0.0f;                /* quarter pulses */
    case 4: return ph < 0.5f ? sinf(12.5663706f * ph) : 0.0f;                /* double speed half */
    case 5: return ph < 0.5f ? fabsf(sinf(12.5663706f * ph)) : 0.0f;
    case 6: return ph < 0.5f ? 1.0f : -1.0f;                                 /* square */
    default: return (ph < 0.5f ? 1.0f : -1.0f) * (1.0f - 2.0f * fmodf(ph, 0.5f));  /* decaying square */
    }
}

typedef struct { sk_env env[4]; float ph[4], fb1, fb2, lph, vel; int note; } tx_voice;

static void tx_vinit(void *vv, float sr) { tx_voice *v = (tx_voice *)vv; (void)sr; memset(v, 0, sizeof *v); for (int k = 0; k < 4; k++) sk_env_init(&v->env[k]); }
static void tx_von(void *vv, const float *p, int note, float vel, int first, float sr)
{
    tx_voice *v = (tx_voice *)vv; (void)p; (void)first; (void)sr;
    v->note = note; v->vel = vel; v->lph = 0.0f; v->fb1 = v->fb2 = 0.0f;
    for (int k = 0; k < 4; k++) { v->ph[k] = 0.0f; sk_env_on(&v->env[k], 1); }
}
static void tx_voff(void *vv, const float *p) { tx_voice *v = (tx_voice *)vv; (void)p; for (int k = 0; k < 4; k++) sk_env_off(&v->env[k]); }

static int tx_vrender(void *vv, const float *p, const sk_glob *g, float *out, int n)
{
    tx_voice *v = (tx_voice *)vv; float sr = g->sr;
    int algo = SK_SW(p, TX_ALGO, 8), ncar = 0, wave[4]; float inc[4], amp[4], velamt = p[TX_VEL];
    for (int k = 0; k < 4; k++) {
        const float *q = p + TX_OP(k);
        int ri = SK_SW(q, TO_RATIO, 16); wave[k] = SK_SW(q, TO_WAVE, 8);
        float semi = (q[TO_FINE] - 0.5f) * 1.0f;
        inc[k] = tx_ratio_tab[ri] * sk_mtof((float)v->note + g->bend + semi) / sr;
        float lv = q[TO_LEVEL]; amp[k] = lv < 0.003f ? 0.0f : expf((lv - 1.0f) * 5.5f);
        sk_env_set(&v->env[k], 0.0015f * powf(2000.0f, q[TO_A]), 0.004f * powf(1500.0f, q[TO_D]), q[TO_S], 0.004f * powf(1500.0f, q[TO_R]), sr);
        if (tx_car[algo] & (1 << k)) ncar++;
    }
    float outg = 0.9f / sqrtf((float)(ncar > 0 ? ncar : 1)) * p[TX_VOL] * 1.6f;
    float fb = p[TX_FB] * 0.6f, vs = 1.0f - velamt * (1.0f - v->vel);
    float lr = sk_expmap(p[TX_LFORATE], 0.1f, 20.0f), lpm = p[TX_LFOPM] * p[TX_LFOPM] * 0.5f * (1.0f + g->mod), lam = p[TX_LFOAM];
    int alive = 0;
    for (int i = 0; i < n; i++) {
        float e[4], o[4] = { 0, 0, 0, 0 };
        for (int k = 0; k < 4; k++) { e[k] = sk_env_tick(&v->env[k]); if (v->env[k].st != SK_ENV_IDLE) alive = 1; }
        v->lph += lr / sr; if (v->lph >= 1.0f) v->lph -= 1.0f;
        float l = v->lph < 0.5f ? 4.0f * v->lph - 1.0f : 3.0f - 4.0f * v->lph;
        float pm = 1.0f + l * lpm * 0.06f, am = 1.0f - lam * 0.5f * (1.0f + l);
        float sum = 0.0f;
        for (int k = 3; k >= 0; k--) {
            float m = 0.0f; unsigned mask = tx_mod[algo][k];
            for (int j = 0; j < 4; j++) if (mask & (1u << j)) m += o[j];
            if (k == 3) m += fb * 0.5f * (v->fb1 + v->fb2);
            v->ph[k] += inc[k] * pm; if (v->ph[k] >= 1.0f) v->ph[k] -= 1.0f;
            float ph = v->ph[k] + m * 1.2f; ph -= floorf(ph);
            o[k] = tx_wave(wave[k], ph) * amp[k] * e[k] * vs;
            if (k == 3) { v->fb2 = v->fb1; v->fb1 = o[3]; }
            if (tx_car[algo] & (1 << k)) sum += o[k];
        }
        out[i] += sum * outg * am;
    }
    return alive;
}

static const sk_def tx_def = {
    "tx81z", TX_COUNT, tx_params, (int)(sizeof tx_presets / sizeof tx_presets[0]), tx_presets,
    8, 0, -1, sizeof(tx_voice), 0,
    tx_vinit, tx_von, tx_voff, tx_vrender, 0, 0
};
